# chunk :: ([1, 2, 3, 4, 5], 2)
def chunk(xs, n):
    if n <= 0:
        raise ValueError("n must be > 0")
    return [xs[i:i + n] for i in range(0, len(xs), n)]

if __name__ == "__main__":
    print(chunk(([1, 2, 3, 4, 5], 2)))

